<script setup>
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { getDormCheckin, listAvailableDormBeds, listDormCheckins, checkoutDormCheckin, transferDormCheckin } from '../api/adminDorm'
const query=reactive({studentName:'',studentNo:'',roomNo:'',checkinStatus:'',studentStatus:'',page:1,size:10});const rows=ref([]);const total=ref(0);const detail=ref(null);const detailOpen=ref(false);const actionOpen=ref(false);const submitting=ref(false);const action=ref('');const current=ref(null);const form=reactive({reason:'',targetBedId:null});const targets=ref([])
async function load(){const d=await listDormCheckins({...query,studentName:query.studentName||undefined,studentNo:query.studentNo||undefined,roomNo:query.roomNo||undefined,checkinStatus:query.checkinStatus||undefined,studentStatus:query.studentStatus||undefined});rows.value=d.records;total.value=d.total}
async function show(row){detail.value=await getDormCheckin(row.id);detailOpen.value=true}
async function begin(row,type){current.value=row;action.value=type;form.reason='';form.targetBedId=null;if(type==='transfer')targets.value=await listAvailableDormBeds({});actionOpen.value=true}
async function submit(){if(!form.reason.trim())return ElMessage.warning('请填写办理原因');if(action.value==='transfer'&&!form.targetBedId)return ElMessage.warning('请选择目标床位');await ElMessageBox.confirm(action.value==='checkout'?'确认办理退宿吗？':'确认办理换寝吗？','二次确认',{type:'warning'});submitting.value=true;try{if(action.value==='checkout')await checkoutDormCheckin(current.value.id,{reason:form.reason.trim()});else await transferDormCheckin(current.value.id,{reason:form.reason.trim(),targetBedId:form.targetBedId});ElMessage.success('办理成功');actionOpen.value=false;await load();if(detailOpen.value)detail.value=await getDormCheckin(current.value.id)}finally{submitting.value=false}}
onMounted(load)
</script>
<template><section class="page"><el-card><el-form inline><el-form-item label="学生姓名"><el-input v-model="query.studentName" clearable/></el-form-item><el-form-item label="学号"><el-input v-model="query.studentNo" clearable/></el-form-item><el-form-item label="寝室"><el-input v-model="query.roomNo" clearable/></el-form-item><el-form-item label="入住状态"><el-select v-model="query.checkinStatus" clearable><el-option label="当前入住" value="ACTIVE"/><el-option label="已退宿" value="CHECKED_OUT"/></el-select></el-form-item><el-form-item label="学籍状态"><el-input v-model="query.studentStatus" clearable placeholder="如 ENROLLED"/></el-form-item><el-button type="primary" @click="query.page=1;load()">查询</el-button></el-form></el-card><el-card><template #header>入住管理</template><el-table :data="rows"><el-table-column prop="realName" label="学生姓名"/><el-table-column prop="maskedStudentNo" label="学号"/><el-table-column prop="collegeName" label="学院"/><el-table-column prop="majorName" label="专业"/><el-table-column prop="className" label="班级"/><el-table-column prop="studentStatus" label="学籍"/><el-table-column label="住宿位置"><template #default="{row}">{{row.campusName}} {{row.buildingName}} {{row.roomNo}}室 {{row.bedNo}}床</template></el-table-column><el-table-column prop="assetSetNo" label="资产套装"/><el-table-column prop="checkinTime" label="入住时间"/><el-table-column prop="checkinStatus" label="状态"/><el-table-column label="操作" width="190"><template #default="{row}"><el-button link @click="show(row)">详情</el-button><template v-if="row.checkinStatus==='ACTIVE'"><el-button link type="warning" @click="begin(row,'checkout')">办理退宿</el-button><el-button link type="primary" @click="begin(row,'transfer')">换寝</el-button></template></template></el-table-column></el-table><el-pagination v-model:current-page="query.page" v-model:page-size="query.size" :total="total" layout="total, prev, pager, next" @current-change="load"/></el-card><el-dialog v-model="detailOpen" title="入住详情"><el-descriptions v-if="detail" :column="1" border><el-descriptions-item label="学生">{{detail.realName}}（{{detail.maskedStudentNo}}）</el-descriptions-item><el-descriptions-item label="联系电话">{{detail.maskedContactPhone||'—'}}</el-descriptions-item><el-descriptions-item label="位置">{{detail.campusName}} {{detail.buildingName}} {{detail.roomNo}}室 {{detail.bedNo}}床</el-descriptions-item><el-descriptions-item label="资产套装">{{detail.assetSetNo}}</el-descriptions-item><el-descriptions-item label="入住状态">{{detail.checkinStatus}}</el-descriptions-item><el-descriptions-item label="入住时间">{{detail.checkinTime}}</el-descriptions-item><el-descriptions-item label="结束时间">{{detail.checkoutTime||'—'}}</el-descriptions-item><el-descriptions-item label="办理原因">{{detail.checkoutReason||'—'}}</el-descriptions-item></el-descriptions></el-dialog><el-dialog v-model="actionOpen" :title="action==='checkout'?'办理退宿':'办理换寝'"><el-form label-width="90px"><el-form-item v-if="action==='transfer'" label="目标床位"><el-select v-model="form.targetBedId" filterable><el-option v-for="b in targets" :key="b.bedId" :label="`${b.campusName} ${b.buildingName} ${b.roomNo}室 ${b.bedNo}床 · ${b.assetSetNo}`" :value="b.bedId"/></el-select></el-form-item><el-form-item label="办理原因" required><el-input v-model="form.reason" type="textarea" maxlength="255" show-word-limit/></el-form-item></el-form><template #footer><el-button @click="actionOpen=false">取消</el-button><el-button type="primary" :loading="submitting" @click="submit">确认办理</el-button></template></el-dialog></section></template>
<style scoped>.page{display:grid;gap:16px}.el-pagination{margin-top:16px;justify-content:flex-end}</style>
